<?php
require_once __DIR__.'/includes/auth.php';require_once __DIR__.'/includes/mailer.php';
$message=null;$error=null;
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(!rate_limit('password-reset:'.($_SERVER['REMOTE_ADDR']??'unknown'),5,900))$error='Too many requests. Please try again later.';else{$email=trim($_POST['email']??'');$stmt=db()->prepare('SELECT id,full_name,email FROM users WHERE email=? AND account_status=\'active\' LIMIT 1');$stmt->execute([$email]);$user=$stmt->fetch();if($user){$token=bin2hex(random_bytes(32));db()->prepare('UPDATE password_resets SET used_at=NOW() WHERE user_id=? AND used_at IS NULL')->execute([$user['id']]);db()->prepare('INSERT INTO password_resets (user_id,token_hash,expires_at) VALUES (?,?,DATE_ADD(NOW(),INTERVAL 15 MINUTE))')->execute([$user['id'],hash('sha256',$token)]);$url=((!empty($_SERVER['HTTPS'])&&$_SERVER['HTTPS']!=='off')?'https':'http').'://'.($_SERVER['HTTP_HOST']??'localhost').rtrim(dirname($_SERVER['SCRIPT_NAME']??''),'/').'/reset_password.php?token='.rawurlencode($token);send_notification($user['email'],'Reset your Barangay password','<p>Hello '.h($user['full_name']).'. Use this link within 15 minutes to reset your password:</p><p><a href="'.h($url).'">Reset password</a></p>');audit_action('password_reset_requested','users',(int)$user['id']);}$message='If an active account matches that email, a password reset link has been sent.';}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Forgot password · Barangay Information System</title><link rel="stylesheet" href="assets/app.css"></head><body class="login-page"><div class="login-card"><div class="brand login-brand"><div class="brand-mark"><span></span><span></span></div><div><strong>Barangay</strong><small>information system</small></div></div><div class="eyebrow">Account recovery</div><h1>Reset your password.</h1><p class="login-copy">Enter your registered email. We will send a short-lived reset link without revealing whether an account exists.</p><?php if($error): ?><div class="flash error"><?= h($error) ?></div><?php endif; ?><?php if($message): ?><div class="flash success"><?= h($message) ?></div><?php endif; ?><form method="post" class="login-form"><input type="hidden" name="csrf" value="<?= h(csrf_token()) ?>"><label>Registered email<input type="email" name="email" required autocomplete="email"></label><button class="primary-button full-button">Send reset link</button></form><a class="text-button" href="login.php">Back to sign in</a></div></body></html>
